import { IDyadicNode, dyadicMachine, ISystemResourceLedger } from './dyadicMachine.js';
export { ISystemResourceLedger };

// =====================================================================
// 1. Tokenizer
// =====================================================================

export type TokenType =
  | 'KEYWORD'
  | 'IDENT'
  | 'NUMBER'
  | 'STRING'
  | 'OPERATOR'
  | 'PUNCT'
  | 'EOF';

export interface IToken {
  type: TokenType;
  value: string;
  line: number;
}

const KEYWORDS = new Set([
  'function',
  'rule',
  'var',
  'begin',
  'end',
  'return',
  'for',
  'each',
  'in',
  'to',
  'do',
  'if',
  'then',
  'else',
  'while',
  'or',
  'and',
  'not',
  'mod',
]);

export function tokenize(source: string): IToken[] {
  const tokens: IToken[] = [];
  const lines = source.split('\n');

  for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
    const lineNum = lineIdx + 1;
    let line = lines[lineIdx];

    // Strip comments
    const commentIdx = line.indexOf('//');
    if (commentIdx >= 0) {
      line = line.substring(0, commentIdx);
    }

    let col = 0;
    while (col < line.length) {
      const ch = line[col];

      // Skip whitespace
      if (/\s/.test(ch)) {
        col++;
        continue;
      }

      // Three-character & two-character operators
      const three = line.substring(col, col + 3);
      if (three === '::=') {
        tokens.push({ type: 'OPERATOR', value: three, line: lineNum });
        col += 3;
        continue;
      }

      const two = line.substring(col, col + 2);
      if ([':=', '<=', '>=', '!=', '<>', '++', '..'].includes(two)) {
        tokens.push({ type: 'OPERATOR', value: two, line: lineNum });
        col += 2;
        continue;
      }

      // Unicode logical keywords
      if (ch === '∧') {
        tokens.push({ type: 'KEYWORD', value: 'and', line: lineNum });
        col++;
        continue;
      }
      if (ch === '∨') {
        tokens.push({ type: 'KEYWORD', value: 'or', line: lineNum });
        col++;
        continue;
      }
      if (ch === '¬') {
        tokens.push({ type: 'KEYWORD', value: 'not', line: lineNum });
        col++;
        continue;
      }

      // Single character operators & special Unicode math
      if (['≔', '≫', '≪', '⊕', '⊖', '⊗', '⊘', '≠', '≤', '≥', '+', '-', '*', '/', '%', '<', '>', '='].includes(ch)) {
        tokens.push({ type: 'OPERATOR', value: ch, line: lineNum });
        col++;
        continue;
      }

      // Punctuation
      if (['(', ')', '[', ']', ';', ':', ',', '.'].includes(ch)) {
        // Special case for root node literal "[]"
        if (ch === '[' && col + 1 < line.length && line[col + 1] === ']') {
          tokens.push({ type: 'IDENT', value: '[]', line: lineNum });
          col += 2;
          continue;
        }
        tokens.push({ type: 'PUNCT', value: ch, line: lineNum });
        col++;
        continue;
      }

      // String literals: '...'
      if (ch === "'") {
        let strVal = '';
        col++;
        while (col < line.length && line[col] !== "'") {
          strVal += line[col];
          col++;
        }
        if (col < line.length && line[col] === "'") col++;
        tokens.push({ type: 'STRING', value: strVal, line: lineNum });
        continue;
      }

      // Numbers
      if (/\d/.test(ch)) {
        let numVal = '';
        while (col < line.length && /[\d.]/.test(line[col])) {
          // Guard against parsing ".." as part of a decimal number
          if (line[col] === '.' && col + 1 < line.length && line[col + 1] === '.') {
            break;
          }
          numVal += line[col];
          col++;
        }
        tokens.push({ type: 'NUMBER', value: numVal, line: lineNum });
        continue;
      }

      // Identifiers & Keywords
      if (/[a-zA-Z_]/.test(ch)) {
        let ident = '';
        while (col < line.length && /[a-zA-Z0-9_]/.test(line[col])) {
          ident += line[col];
          col++;
        }
        const lower = ident.toLowerCase();
        if (KEYWORDS.has(lower)) {
          tokens.push({ type: 'KEYWORD', value: lower, line: lineNum });
        } else {
          tokens.push({ type: 'IDENT', value: ident, line: lineNum });
        }
        continue;
      }

      // Unknown character, skip
      col++;
    }
  }

  tokens.push({ type: 'EOF', value: '', line: lines.length + 1 });
  return tokens;
}

// =====================================================================
// 2. Abstract Syntax Tree (AST)
// =====================================================================

export type ASTExpr =
  | { type: 'LITERAL'; value: any; line: number }
  | { type: 'IDENT'; name: string; line: number }
  | { type: 'BINARY'; op: string; left: ASTExpr; right: ASTExpr; line: number }
  | { type: 'UNARY'; op: string; expr: ASTExpr; line: number }
  | { type: 'CALL'; callee: string; args: ASTExpr[]; line: number }
  | { type: 'SLICE'; target: ASTExpr; start: ASTExpr; end: ASTExpr; line: number }
  | { type: 'INDEX'; target: ASTExpr; index: ASTExpr; line: number }
  | { type: 'TUPLE'; elements: ASTExpr[]; line: number };

export type ASTStmt =
  | { type: 'ASSIGN'; line: number; target: string | string[]; indexExpr?: ASTExpr; expr: ASTExpr }
  | { type: 'IF'; line: number; cond: ASTExpr; thenBranch: ASTStmt[]; elseBranch?: ASTStmt[] }
  | { type: 'WHILE'; line: number; cond: ASTExpr; body: ASTStmt[] }
  | { type: 'FOR'; line: number; varName: string; start: ASTExpr; end: ASTExpr; body: ASTStmt[] }
  | { type: 'FOR_EACH'; line: number; itemVar: string; setExpr: ASTExpr; body: ASTStmt[] }
  | { type: 'RETURN'; line: number; expr: ASTExpr }
  | { type: 'CALL_STMT'; line: number; call: ASTExpr };

export interface IFunctionDef {
  name: string;
  params: string[];
  localVars: string[];
  body: ASTStmt[];
  line: number;
}

export interface IProgram {
  functions: Map<string, IFunctionDef>;
}

// =====================================================================
// 3. Parser
// =====================================================================

export class PseudoParser {
  private tokens: IToken[];
  private pos: number = 0;

  constructor(tokens: IToken[]) {
    this.tokens = tokens;
  }

  private peek(): IToken {
    return this.tokens[this.pos];
  }

  private peekNext(): IToken {
    return this.tokens[Math.min(this.pos + 1, this.tokens.length - 1)];
  }

  private advance(): IToken {
    const tok = this.tokens[this.pos];
    if (this.pos < this.tokens.length - 1) this.pos++;
    return tok;
  }

  private check(type: TokenType, val?: string): boolean {
    const tok = this.peek();
    if (tok.type !== type) return false;
    if (val !== undefined && tok.value !== val) return false;
    return true;
  }

  private match(type: TokenType, val?: string): boolean {
    if (this.check(type, val)) {
      this.advance();
      return true;
    }
    return false;
  }

  private expect(type: TokenType, val?: string): IToken {
    const tok = this.peek();
    if (!this.check(type, val)) {
      throw new Error(
        `Parser Error at line ${tok.line}: Expected ${val || type}, got "${tok.value}"`
      );
    }
    return this.advance();
  }

  public parseProgram(): IProgram {
    const functions = new Map<string, IFunctionDef>();

    while (!this.check('EOF')) {
      if (this.check('KEYWORD', 'function') || this.check('KEYWORD', 'rule')) {
        const fn = this.parseFunction();
        functions.set(fn.name, fn);
      } else {
        // Skip unexpected tokens until next function
        this.advance();
      }
    }

    return { functions };
  }

  private parseFunction(): IFunctionDef {
    let fnTok: IToken;
    if (this.check('KEYWORD', 'rule')) {
      fnTok = this.expect('KEYWORD', 'rule');
    } else {
      fnTok = this.expect('KEYWORD', 'function');
    }
    const nameTok = this.expect('IDENT');
    const name = nameTok.value;

    this.expect('PUNCT', '(');
    const params: string[] = [];
    while (!this.check('PUNCT', ')') && !this.check('EOF')) {
      const pName = this.expect('IDENT').value;
      if (this.match('PUNCT', ':')) {
        // Skip type annotation (e.g. Node, Integer, etc.)
        this.skipType();
      }
      params.push(pName);
      if (this.match('PUNCT', ';')) continue;
      if (this.match('PUNCT', ',')) continue;
    }
    this.expect('PUNCT', ')');

    // Skip return type if present: ": (Set of Node, Set of Node)" or ": Node" or ": 𝔹"
    if (this.match('PUNCT', ':')) {
      this.skipType();
    }

    // Optional directed equality symbol: "rule Foo(...): Type ≔" or "::=" or ":="
    if (
      this.check('OPERATOR', '≔') ||
      this.check('OPERATOR', '::=') ||
      this.check('OPERATOR', ':=') ||
      this.check('OPERATOR', '=')
    ) {
      this.advance();
    }

    // Optional "var" section
    const localVars: string[] = [];
    if (this.match('KEYWORD', 'var')) {
      while (!this.check('KEYWORD', 'begin') && !this.check('EOF')) {
        // Names list: "XL, XR: Set of Node;"
        const varNames: string[] = [];
        do {
          varNames.push(this.expect('IDENT').value);
        } while (this.match('PUNCT', ','));

        if (this.match('PUNCT', ':')) {
          this.skipType();
        }
        this.match('PUNCT', ';');
        localVars.push(...varNames);
      }
    }

    this.expect('KEYWORD', 'begin');
    const body: ASTStmt[] = [];
    while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
      body.push(this.parseStatement());
    }
    this.expect('KEYWORD', 'end');
    this.match('PUNCT', ';'); // Optional trailing semicolon after function end

    return {
      name,
      params,
      localVars,
      body,
      line: fnTok.line,
    };
  }

  private skipType(): void {
    if (this.match('PUNCT', '(')) {
      while (!this.check('PUNCT', ')') && !this.check('EOF')) {
        this.advance();
      }
      this.expect('PUNCT', ')');
    } else {
      while (
        !this.check('PUNCT', ';') &&
        !this.check('PUNCT', ',') &&
        !this.check('PUNCT', ')') &&
        !this.check('KEYWORD', 'begin') &&
        !this.check('KEYWORD', 'var') &&
        !this.check('OPERATOR', '≔') &&
        !this.check('OPERATOR', '::=') &&
        !this.check('OPERATOR', ':=') &&
        !this.check('OPERATOR', '=') &&
        !this.check('EOF')
      ) {
        this.advance();
      }
    }
  }

  private parseStatement(): ASTStmt {
    const tok = this.peek();

    // 1. If statement
    if (this.match('KEYWORD', 'if')) {
      const cond = this.parseExpr();
      this.expect('KEYWORD', 'then');
      let thenBranch: ASTStmt[] = [];
      if (this.match('KEYWORD', 'begin')) {
        while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
          thenBranch.push(this.parseStatement());
        }
        this.expect('KEYWORD', 'end');
        this.match('PUNCT', ';');
      } else {
        thenBranch.push(this.parseStatement());
      }

      let elseBranch: ASTStmt[] | undefined = undefined;
      if (this.match('KEYWORD', 'else')) {
        elseBranch = [];
        if (this.match('KEYWORD', 'begin')) {
          while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
            elseBranch.push(this.parseStatement());
          }
          this.expect('KEYWORD', 'end');
          this.match('PUNCT', ';');
        } else {
          elseBranch.push(this.parseStatement());
        }
      }

      return { type: 'IF', line: tok.line, cond, thenBranch, elseBranch };
    }

    // 2. While loop
    if (this.match('KEYWORD', 'while')) {
      const cond = this.parseExpr();
      this.expect('KEYWORD', 'do');
      const body: ASTStmt[] = [];
      if (this.match('KEYWORD', 'begin')) {
        while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
          body.push(this.parseStatement());
        }
        this.expect('KEYWORD', 'end');
        this.match('PUNCT', ';');
      } else {
        body.push(this.parseStatement());
      }
      return { type: 'WHILE', line: tok.line, cond, body };
    }

    // 3. For loop: "for i := start to end do" or "for each item in set do"
    if (this.match('KEYWORD', 'for')) {
      if (this.match('KEYWORD', 'each')) {
        const itemVar = this.expect('IDENT').value;
        this.expect('KEYWORD', 'in');
        const setExpr = this.parseExpr();
        this.expect('KEYWORD', 'do');
        const body: ASTStmt[] = [];
        if (this.match('KEYWORD', 'begin')) {
          while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
            body.push(this.parseStatement());
          }
          this.expect('KEYWORD', 'end');
          this.match('PUNCT', ';');
        } else {
          body.push(this.parseStatement());
        }
        return { type: 'FOR_EACH', line: tok.line, itemVar, setExpr, body };
      } else {
        const varName = this.expect('IDENT').value;
        this.expect('OPERATOR', ':=');
        const start = this.parseExpr();
        this.expect('KEYWORD', 'to');
        const end = this.parseExpr();
        this.expect('KEYWORD', 'do');
        const body: ASTStmt[] = [];
        if (this.match('KEYWORD', 'begin')) {
          while (!this.check('KEYWORD', 'end') && !this.check('EOF')) {
            body.push(this.parseStatement());
          }
          this.expect('KEYWORD', 'end');
          this.match('PUNCT', ';');
        } else {
          body.push(this.parseStatement());
        }
        return { type: 'FOR', line: tok.line, varName, start, end, body };
      }
    }

    // 4. Return statement
    if (this.match('KEYWORD', 'return')) {
      const expr = this.parseExpr();
      this.match('PUNCT', ';');
      return { type: 'RETURN', line: tok.line, expr };
    }

    // 5. Tuple assignment: (XL, XR) := ...
    if (this.check('PUNCT', '(') && this.peekNext().type === 'IDENT') {
      this.advance(); // consume '('
      const targets: string[] = [];
      do {
        targets.push(this.expect('IDENT').value);
      } while (this.match('PUNCT', ','));
      this.expect('PUNCT', ')');
      this.expect('OPERATOR', ':=');
      const expr = this.parseExpr();
      this.match('PUNCT', ';');
      return { type: 'ASSIGN', line: tok.line, target: targets, expr };
    }

    // 6. Identifier-led: assignment (x := ... or x[i] := ...) or procedure call (Insert(...))
    if (this.check('IDENT')) {
      const name = this.advance().value;
      if (this.match('PUNCT', '[')) {
        const indexExpr = this.parseExpr();
        this.expect('PUNCT', ']');
        this.expect('OPERATOR', ':=');
        const expr = this.parseExpr();
        this.match('PUNCT', ';');
        return { type: 'ASSIGN', line: tok.line, target: name, indexExpr, expr };
      }
      if (this.match('OPERATOR', ':=')) {
        const expr = this.parseExpr();
        this.match('PUNCT', ';');
        return { type: 'ASSIGN', line: tok.line, target: name, expr };
      }
      if (this.match('PUNCT', '(')) {
        const args: ASTExpr[] = [];
        while (!this.check('PUNCT', ')') && !this.check('EOF')) {
          args.push(this.parseExpr());
          this.match('PUNCT', ',');
        }
        this.expect('PUNCT', ')');
        this.match('PUNCT', ';');
        return {
          type: 'CALL_STMT',
          line: tok.line,
          call: { type: 'CALL', callee: name, args, line: tok.line },
        };
      }
    }

    // Fallback: advance to prevent infinite loop
    this.advance();
    this.match('PUNCT', ';');
    return {
      type: 'CALL_STMT',
      line: tok.line,
      call: { type: 'LITERAL', value: null, line: tok.line },
    };
  }

  // --- Expression Parser with Precedence ---

  private parseExpr(): ASTExpr {
    return this.parseLogicalOr();
  }

  private parseLogicalOr(): ASTExpr {
    let expr = this.parseLogicalAnd();
    while (this.match('KEYWORD', 'or')) {
      const right = this.parseLogicalAnd();
      expr = { type: 'BINARY', op: 'or', left: expr, right, line: expr.line };
    }
    return expr;
  }

  private parseLogicalAnd(): ASTExpr {
    let expr = this.parseComparison();
    while (this.match('KEYWORD', 'and')) {
      const right = this.parseComparison();
      expr = { type: 'BINARY', op: 'and', left: expr, right, line: expr.line };
    }
    return expr;
  }

  private parseComparison(): ASTExpr {
    let expr = this.parseAdditive();
    while (['<', '<=', '>', '>=', '=', '!=', '<>', '≠', '≤', '≥'].includes(this.peek().value)) {
      const op = this.advance().value;
      const right = this.parseAdditive();
      expr = { type: 'BINARY', op, left: expr, right, line: expr.line };
    }
    return expr;
  }

  private parseAdditive(): ASTExpr {
    let expr = this.parseMultiplicative();
    while (['+', '-', '++', '⊕', '⊖'].includes(this.peek().value)) {
      const op = this.advance().value;
      const right = this.parseMultiplicative();
      expr = { type: 'BINARY', op, left: expr, right, line: expr.line };
    }
    return expr;
  }

  private parseMultiplicative(): ASTExpr {
    let expr = this.parsePrimary();
    while (['*', '/', '%', 'mod', '≫', '≪', '⊗', '⊘'].includes(this.peek().value)) {
      const op = this.advance().value;
      const right = this.parsePrimary();
      expr = { type: 'BINARY', op, left: expr, right, line: expr.line };
    }
    return expr;
  }

  private parsePrimary(): ASTExpr {
    const tok = this.peek();

    // String literal
    if (this.match('STRING')) {
      return { type: 'LITERAL', value: tok.value, line: tok.line };
    }

    // Number literal
    if (this.match('NUMBER')) {
      return { type: 'LITERAL', value: Number(tok.value), line: tok.line };
    }

    // Root node literal: "[]"
    if (tok.value === '[]') {
      this.advance();
      return { type: 'LITERAL', value: dyadicMachine.root(), line: tok.line };
    }

    // Parenthesized expression or tuple: (a, b)
    if (this.match('PUNCT', '(')) {
      const first = this.parseExpr();
      if (this.match('PUNCT', ',')) {
        const elements: ASTExpr[] = [first];
        do {
          elements.push(this.parseExpr());
        } while (this.match('PUNCT', ','));
        this.expect('PUNCT', ')');
        return { type: 'TUPLE', elements, line: tok.line };
      }
      this.expect('PUNCT', ')');
      return first;
    }

    // Function call or Slicing: X[0 .. i]
    if (this.check('IDENT')) {
      const name = this.advance().value;

      // Function Call: Func(a, b)
      if (this.match('PUNCT', '(')) {
        const args: ASTExpr[] = [];
        while (!this.check('PUNCT', ')') && !this.check('EOF')) {
          args.push(this.parseExpr());
          this.match('PUNCT', ',');
        }
        this.expect('PUNCT', ')');
        return { type: 'CALL', callee: name, args, line: tok.line };
      }

      // Slicing: X[0 .. i] or Indexing: X[i]
      if (this.match('PUNCT', '[')) {
        const first = this.parseExpr();
        if (this.match('OPERATOR', '..')) {
          const end = this.parseExpr();
          this.expect('PUNCT', ']');
          return {
            type: 'SLICE',
            target: { type: 'IDENT', name, line: tok.line },
            start: first,
            end,
            line: tok.line,
          };
        } else {
          this.expect('PUNCT', ']');
          return {
            type: 'INDEX',
            target: { type: 'IDENT', name, line: tok.line },
            index: first,
            line: tok.line,
          };
        }
      }

      return { type: 'IDENT', name, line: tok.line };
    }

    // Fallback
    this.advance();
    return { type: 'LITERAL', value: null, line: tok.line };
  }
}

// =====================================================================
// 4. Runtime Environment & Stepper Execution
// =====================================================================

export interface IExecutionTelemetry {
  callCount: number;
  maxCallDepth: number;
  stepCount: number;
  cutCount: number;
}

export interface IStepState {
  currentLine: number;
  callStack: string[];
  variables: Record<string, string>;
  isDone: boolean;
  result?: any;
  error?: string;
  telemetry: IExecutionTelemetry;
  systemLedger?: ISystemResourceLedger;
}

export class ExecutionScope {
  public vars = new Map<string, any>();
  public parent?: ExecutionScope;

  constructor(parent?: ExecutionScope) {
    this.parent = parent;
  }

  public get(name: string): any {
    if (this.vars.has(name)) return this.vars.get(name);
    if (this.parent) return this.parent.get(name);
    return undefined;
  }

  public set(name: string, val: any): void {
    if (this.vars.has(name) || !this.parent) {
      this.vars.set(name, val);
    } else {
      this.parent.set(name, val);
    }
  }

  public define(name: string, val: any): void {
    this.vars.set(name, val);
  }

  public formatVariables(systemLedger?: ISystemResourceLedger): Record<string, string> {
    const res: Record<string, string> = {};
    for (const [k, v] of this.vars.entries()) {
      res[k] = formatRuntimeValue(v);
    }
    if (
      systemLedger &&
      (systemLedger.addCount > 0 ||
        systemLedger.cutCount > 0 ||
        systemLedger.mulCount > 0 ||
        systemLedger.maxDepth > 0)
    ) {
      res['[sys] addCount'] = String(systemLedger.addCount);
      res['[sys] cutCount'] = String(systemLedger.cutCount);
      if (systemLedger.mulCount > 0) res['[sys] mulCount'] = String(systemLedger.mulCount);
      if (systemLedger.maxDepth > 0) res['[sys] maxDepth'] = String(systemLedger.maxDepth);
    }
    return res;
  }
}

export function formatRuntimeValue(val: any): string {
  if (val === null || val === undefined) return 'nil';
  if (typeof val === 'number') return val.toString();
  if (typeof val === 'string') return `"${val}"`;
  if (val instanceof Set) {
    const items = [...val].map((v) => formatRuntimeValue(v)).join(', ');
    return `{ ${items} }`;
  }
  if (Array.isArray(val)) {
    return `( ${val.map((v) => formatRuntimeValue(v)).join(', ')} )`;
  }
  if (typeof val === 'object' && 'path' in val && typeof val.format === 'function') {
    const pStr = val.path === '' ? '[]' : `[${val.path}]`;
    return `${pStr} (${val.format()})`;
  }
  return String(val);
}

/**
 * Interactive Stepper Engine for Structured Pseudocode.
 */
export class PseudoInterpreter {
  public program: IProgram;
  public callStack: string[] = [];
  public telemetry: IExecutionTelemetry = {
    callCount: 0,
    maxCallDepth: 0,
    stepCount: 0,
    cutCount: 0,
  };
  public systemLedger: ISystemResourceLedger = {
    addCount: 0,
    mulCount: 0,
    cutCount: 0,
    maxDepth: 0,
  };

  constructor(source: string) {
    const tokens = tokenize(source);
    const parser = new PseudoParser(tokens);
    this.program = parser.parseProgram();
  }

  /**
   * Generator producing step-by-step states for interactive execution and line highlighting.
   */
  public *runStepper(
    entryFunctionName: string,
    args: any[]
  ): Generator<IStepState, IStepState, void> {
    const fn = this.program.functions.get(entryFunctionName);
    if (!fn) {
      const err = `Function "${entryFunctionName}" not found in program.`;
      return {
        currentLine: 1,
        callStack: [],
        variables: {},
        isDone: true,
        error: err,
        telemetry: { ...this.telemetry },
      };
    }

    const globalScope = new ExecutionScope();
    this.callStack = [];
    this.telemetry = {
      callCount: 0,
      maxCallDepth: 0,
      stepCount: 0,
      cutCount: 0,
    };
    this.systemLedger = {
      addCount: 0,
      mulCount: 0,
      cutCount: 0,
      maxDepth: 0,
    };

    try {
      const result = yield* this.executeFunction(fn, args, globalScope);
      return {
        currentLine: fn.line,
        callStack: [],
        variables: {},
        isDone: true,
        result,
        telemetry: { ...this.telemetry },
      };
    } catch (e: any) {
      return {
        currentLine: 1,
        callStack: this.callStack,
        variables: {},
        isDone: true,
        error: e.message || String(e),
        telemetry: { ...this.telemetry },
      };
    }
  }

  private *executeFunction(
    fn: IFunctionDef,
    args: any[],
    parentScope: ExecutionScope
  ): Generator<IStepState, any, void> {
    const scope = new ExecutionScope(parentScope);
    const callDesc = `${fn.name}(${args.map(formatRuntimeValue).join(', ')})`;
    this.telemetry.callCount++;
    this.callStack.push(callDesc);
    if (this.callStack.length > this.telemetry.maxCallDepth) {
      this.telemetry.maxCallDepth = this.callStack.length;
    }

    // Bind parameters
    for (let i = 0; i < fn.params.length; i++) {
      scope.define(fn.params[i], args[i]);
    }

    // Initialize local variables
    for (const v of fn.localVars) {
      scope.define(v, null);
    }

    // Yield function entry
    yield {
      currentLine: fn.line,
      callStack: [...this.callStack],
      variables: scope.formatVariables(this.systemLedger),
      isDone: false,
      telemetry: { ...this.telemetry },
      systemLedger: { ...this.systemLedger },
    };

    // Execute body statements
    for (const stmt of fn.body) {
      const ret = yield* this.executeStatement(stmt, scope);
      if (ret !== undefined && ret !== null && typeof ret === 'object' && '__RETURN__' in ret) {
        this.callStack.pop();
        return ret.value;
      }
    }

    this.callStack.pop();
    return null;
  }

  private *executeStatement(
    stmt: ASTStmt,
    scope: ExecutionScope
  ): Generator<IStepState, any, void> {
    this.telemetry.stepCount++;
    // Yield current statement execution state before running it
    yield {
      currentLine: stmt.line,
      callStack: [...this.callStack],
      variables: scope.formatVariables(this.systemLedger),
      isDone: false,
      telemetry: { ...this.telemetry },
      systemLedger: { ...this.systemLedger },
    };

    switch (stmt.type) {
      case 'ASSIGN': {
        const val = this.evalExpr(stmt.expr, scope);
        if (stmt.indexExpr) {
          const arr = scope.get(stmt.target as string);
          const idx = Number(this.evalExpr(stmt.indexExpr, scope));
          if (Array.isArray(arr)) {
            arr[idx] = val;
          }
        } else if (Array.isArray(stmt.target)) {
          // Tuple assignment: (XL, XR) := ...
          if (Array.isArray(val)) {
            for (let i = 0; i < stmt.target.length; i++) {
              scope.set(stmt.target[i], val[i]);
            }
          }
        } else {
          scope.set(stmt.target, val);
        }
        break;
      }

      case 'RETURN': {
        const retVal = this.evalExpr(stmt.expr, scope);
        return { __RETURN__: true, value: retVal };
      }

      case 'IF': {
        const cond = this.evalExpr(stmt.cond, scope);
        if (cond) {
          for (const s of stmt.thenBranch) {
            const res = yield* this.executeStatement(s, scope);
            if (res && res.__RETURN__) return res;
          }
        } else if (stmt.elseBranch) {
          for (const s of stmt.elseBranch) {
            const res = yield* this.executeStatement(s, scope);
            if (res && res.__RETURN__) return res;
          }
        }
        break;
      }

      case 'WHILE': {
        let maxIter = 1000;
        while (this.evalExpr(stmt.cond, scope) && maxIter-- > 0) {
          for (const s of stmt.body) {
            const res = yield* this.executeStatement(s, scope);
            if (res && res.__RETURN__) return res;
          }
        }
        break;
      }

      case 'FOR': {
        const startVal = Number(this.evalExpr(stmt.start, scope));
        const endVal = Number(this.evalExpr(stmt.end, scope));
        for (let i = startVal; i <= endVal; i++) {
          scope.set(stmt.varName, i);
          for (const s of stmt.body) {
            const res = yield* this.executeStatement(s, scope);
            if (res && res.__RETURN__) return res;
          }
        }
        break;
      }

      case 'FOR_EACH': {
        const setVal = this.evalExpr(stmt.setExpr, scope);
        const items =
          setVal instanceof Set
            ? [...setVal]
            : Array.isArray(setVal)
            ? setVal
            : [];
        for (const item of items) {
          scope.set(stmt.itemVar, item);
          for (const s of stmt.body) {
            const res = yield* this.executeStatement(s, scope);
            if (res && res.__RETURN__) return res;
          }
        }
        break;
      }

      case 'CALL_STMT': {
        this.evalExpr(stmt.call, scope);
        break;
      }
    }

    return null;
  }

  private evalExpr(expr: ASTExpr, scope: ExecutionScope): any {
    switch (expr.type) {
      case 'LITERAL':
        return expr.value;

      case 'IDENT': {
        if (expr.name === '[]') return dyadicMachine.root();
        if (expr.name === 'nil' || expr.name === 'null') return null;
        if (expr.name === 'pi' || expr.name === 'PI' || expr.name === 'π') return Math.PI;
        if (expr.name === 'e' || expr.name === 'E') return Math.E;
        if (expr.name === 'true' || expr.name === 'TRUE') return true;
        if (expr.name === 'false' || expr.name === 'FALSE') return false;
        const val = scope.get(expr.name);
        if (val !== undefined) return val;
        // Ambient system resource ledger variables
        if (expr.name === 'addCount' || expr.name === 'addCalls') return this.systemLedger.addCount;
        if (expr.name === 'mulCount' || expr.name === 'mulCalls') return this.systemLedger.mulCount;
        if (expr.name === 'cutCount' || expr.name === 'cutCalls') return this.systemLedger.cutCount;
        if (expr.name === 'maxDepth') return this.systemLedger.maxDepth;
        return undefined;
      }

      case 'TUPLE':
        return expr.elements.map((e) => this.evalExpr(e, scope));

      case 'UNARY': {
        const val = this.evalExpr(expr.expr, scope);
        if (expr.op === 'not') return !val;
        if (expr.op === '-') {
          if (val && typeof val === 'object' && 'path' in val) {
            return dyadicMachine.conwayNeg(val);
          }
          return -val;
        }
        return val;
      }

      case 'BINARY': {
        const left = this.evalExpr(expr.left, scope);
        const right = this.evalExpr(expr.right, scope);

        // Logical
        if (expr.op === 'or') return Boolean(left || right);
        if (expr.op === 'and') return Boolean(left && right);

        // Tree concatenation: candidate ++ '+'
        if (expr.op === '++') {
          if (left && typeof left === 'object' && 'path' in left) {
            const nextSign = typeof right === 'string' ? right : '';
            return dyadicMachine.fromPath(left.path + nextSign);
          }
          return String(left) + String(right);
        }

        // Comparison (<, <=, >, >=, =, !=, <>, ≠, ≤, ≥)
        if (['<', '<=', '>', '>=', '=', '!=', '<>', '≠', '≤', '≥'].includes(expr.op)) {
          if (
            left &&
            right &&
            typeof left === 'object' &&
            typeof right === 'object' &&
            'path' in left &&
            'path' in right
          ) {
            const cmp = dyadicMachine.compare(left, right);
            if (expr.op === '<') return cmp === -1;
            if (expr.op === '<=' || expr.op === '≤') return cmp <= 0;
            if (expr.op === '>') return cmp === 1;
            if (expr.op === '>=' || expr.op === '≥') return cmp >= 0;
            if (expr.op === '=') return cmp === 0;
            if (expr.op === '!=' || expr.op === '<>' || expr.op === '≠') return cmp !== 0;
          }
          if (expr.op === '<') return left < right;
          if (expr.op === '<=' || expr.op === '≤') return left <= right;
          if (expr.op === '>') return left > right;
          if (expr.op === '>=' || expr.op === '≥') return left >= right;
          if (expr.op === '=') return left === right;
          if (expr.op === '!=' || expr.op === '<>' || expr.op === '≠') return left !== right;
        }

        // Math & Dyadic Ops
        if (expr.op === '+') {
          if (
            left &&
            right &&
            typeof left === 'object' &&
            typeof right === 'object' &&
            'path' in left &&
            'path' in right
          ) {
            return dyadicMachine.conwayAdd(left, right);
          }
          return left + right;
        }

        if (expr.op === '-') {
          if (
            left &&
            right &&
            typeof left === 'object' &&
            typeof right === 'object' &&
            'path' in left &&
            'path' in right
          ) {
            return dyadicMachine.conwaySub(left, right);
          }
          return left - right;
        }

        if (expr.op === '⊖') return dyadicMachine.sub(left, right);
        if (expr.op === '⊕') return dyadicMachine.add(left, right);
        if (expr.op === '⊗') return dyadicMachine.mul(left, right);
        if (expr.op === '⊘') return dyadicMachine.div(left, right);
        if (expr.op === '*') return left * right;
        if (expr.op === '/') return left / right;
        if (expr.op === 'mod' || expr.op === '%') return left % right;
        if (expr.op === '≫') return dyadicMachine.shift(left, -right);
        if (expr.op === '≪') return dyadicMachine.shift(left, right);

        return null;
      }

      case 'SLICE': {
        const target = this.evalExpr(expr.target, scope);
        const start = Number(this.evalExpr(expr.start, scope));
        const end = Number(this.evalExpr(expr.end, scope));
        if (target && typeof target === 'object' && 'path' in target) {
          // Prefix of length end: proper prefix slice(0, end)
          const p = target.path.slice(start, end);
          return dyadicMachine.fromPath(p);
        }
        return null;
      }

      case 'INDEX': {
        const target = this.evalExpr(expr.target, scope);
        const idx = Number(this.evalExpr(expr.index, scope));
        if (Array.isArray(target)) {
          return target[idx];
        }
        if (target && typeof target === 'object' && 'path' in target) {
          return target.path[idx] ?? '';
        }
        if (typeof target === 'string') {
          return target[idx] ?? '';
        }
        return null;
      }

      case 'CALL': {
        const name = expr.callee;
        const evaluatedArgs = expr.args.map((a) => this.evalExpr(a, scope));

        // Built-in Primitives & Aliases
        if (name === 'EmptySet' || name === 'Set') return new Set<IDyadicNode>();
        if (name === 'Insert' || name === 'include') {
          const s = evaluatedArgs[0];
          if (s instanceof Set) s.add(evaluatedArgs[1]);
          return s;
        }
        if (name === 'Maximum') {
          const s = evaluatedArgs[0];
          const arr = s instanceof Set ? [...s] : [];
          return arr.length > 0 ? dyadicMachine.max(arr) : null;
        }
        if (name === 'Minimum') {
          const s = evaluatedArgs[0];
          const arr = s instanceof Set ? [...s] : [];
          return arr.length > 0 ? dyadicMachine.min(arr) : null;
        }
        if (name === 'length' || name === 'birthday') {
          const item = evaluatedArgs[0];
          if (item && typeof item === 'object' && 'path' in item) {
            return item.path.length;
          }
          return typeof item === 'string' ? item.length : 0;
        }
        if (name === 'sqr') return dyadicMachine.mul(evaluatedArgs[0], evaluatedArgs[0]);
        if (name === 'val' || name === 'to_dyadic') return evaluatedArgs[0];
        if (name === 'node' || name === 'to_node') return dyadicMachine.node(evaluatedArgs[0]);

        // Standard Math & Nonstandard Analysis Primitives
        if (name === 'sin') return Math.sin(Number(evaluatedArgs[0]));
        if (name === 'cos') return Math.cos(Number(evaluatedArgs[0]));
        if (name === 'tan') return Math.tan(Number(evaluatedArgs[0]));
        if (name === 'sqrt') return Math.sqrt(Number(evaluatedArgs[0]));
        if (name === 'abs') return Math.abs(Number(evaluatedArgs[0]));
        if (name === 'st') {
          const v = evaluatedArgs[0];
          if (v && typeof v === 'object' && 'st' in v) return v.st;
          return Number(v);
        }
        if (name === 'eps') {
          const v = evaluatedArgs[0];
          if (v && typeof v === 'object' && 'eps' in v) return v.eps;
          return 0;
        }
        if (name === 'near') {
          const tol = evaluatedArgs[2] !== undefined ? Number(evaluatedArgs[2]) : 1e-7;
          return Math.abs(Number(evaluatedArgs[0]) - Number(evaluatedArgs[1])) <= tol;
        }
        if (name === 'divides' || name === 'div') {
          const d = Number(evaluatedArgs[0]);
          const n = Number(evaluatedArgs[1]);
          return d !== 0 && (n % d === 0);
        }
        if (name === 'even') return Math.round(Number(evaluatedArgs[0])) % 2 === 0;
        if (name === 'odd') return Math.abs(Math.round(Number(evaluatedArgs[0])) % 2) === 1;
        if (name === 'succ') return Number(evaluatedArgs[0]) + 1;
        if (name === 'pred') return Number(evaluatedArgs[0]) - 1;
        if (name === 'min') return Math.min(...evaluatedArgs.map(Number));
        if (name === 'max') return Math.max(...evaluatedArgs.map(Number));

        if (name === 'CordicAngle' || name === 'CordicAngleTable' || name === 'lookup_angle') {
          const idx = Number(evaluatedArgs[0]);
          const angles = [
            0.7853981633974483, 0.4636476090008061, 0.24497866312686414, 0.12435499454676144,
            0.06241880999595735, 0.031239833430268277, 0.015623728620476831, 0.007812116210182813
          ];
          const val = angles[idx] ?? (0.785398 / Math.pow(2, idx));
          return dyadicMachine.fromFloat(val);
        }
        if (name === 'CreateArray' || name === 'allocate_grid') {
          const len = Number(evaluatedArgs[0]);
          return new Array(len).fill(dyadicMachine.root());
        }
        if (name === 'DyadicAdd') {
          return dyadicMachine.add(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'TreeConcat') {
          const left = evaluatedArgs[0];
          const right = evaluatedArgs[1];
          if (left && typeof left === 'object' && 'path' in left) {
            const nextSign = typeof right === 'string' ? right : '';
            return dyadicMachine.fromPath(left.path + nextSign);
          }
          return String(left) + String(right);
        }
        if (name === 'KinematicStep') {
          const res = dyadicMachine.kinematicStep(evaluatedArgs[0], evaluatedArgs[1], evaluatedArgs[2]);
          return [res.v, res.s];
        }
        if (name === 'CordicRotor') {
          const res = dyadicMachine.cordicSinCos(evaluatedArgs[0], Number(evaluatedArgs[1]));
          return [res.cos, res.sin];
        }
        if (name === 'BayesUpdate') {
          const priorH = dyadicMachine.node(evaluatedArgs[0]);
          const pEgivenH = dyadicMachine.node(evaluatedArgs[1]);
          const pEgivenNotH = dyadicMachine.node(evaluatedArgs[2]);
          const priorNotH = dyadicMachine.sub(1, priorH);
          const jointH = dyadicMachine.mul(priorH, pEgivenH);
          const jointNotH = dyadicMachine.mul(priorNotH, pEgivenNotH);
          const totalEvidence = dyadicMachine.add(jointH, jointNotH);
          return dyadicMachine.div(jointH, totalEvidence);
        }

        // Built-in fallback to dyadicMachine if not defined as AST function
        if (name === 'SimplerOptions') {
          const res = dyadicMachine.simplerOptions(evaluatedArgs[0]);
          return [new Set(res.leftOptions), new Set(res.rightOptions)];
        }
        if (name === 'Cut') {
          this.telemetry.cutCount++;
          this.systemLedger.cutCount++;
          return dyadicMachine.cut(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'ConwayAdd') {
          const stats = dyadicMachine.countConwayAdd(evaluatedArgs[0], evaluatedArgs[1]);
          this.telemetry.callCount += stats.calls;
          this.telemetry.cutCount += stats.cuts;
          this.systemLedger.addCount += stats.calls;
          this.systemLedger.cutCount += stats.cuts;
          if (this.callStack.length + stats.maxDepth > this.telemetry.maxCallDepth) {
            this.telemetry.maxCallDepth = this.callStack.length + stats.maxDepth;
            this.systemLedger.maxDepth = this.telemetry.maxCallDepth;
          }
          return dyadicMachine.conwayAdd(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'ConwaySub') {
          const stats = dyadicMachine.countConwayAdd(evaluatedArgs[0], evaluatedArgs[1]);
          this.telemetry.callCount += stats.calls;
          this.telemetry.cutCount += stats.cuts;
          this.systemLedger.addCount += stats.calls;
          this.systemLedger.cutCount += stats.cuts;
          return dyadicMachine.conwaySub(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'ConwayNeg') {
          return dyadicMachine.conwayNeg(evaluatedArgs[0]);
        }
        if (name === 'ConwayMul') {
          const stats = dyadicMachine.countConwayMul(evaluatedArgs[0], evaluatedArgs[1]);
          this.telemetry.callCount += stats.calls;
          this.telemetry.cutCount += stats.cuts;
          this.systemLedger.mulCount += stats.calls;
          this.systemLedger.addCount += stats.addCalls || 0;
          this.systemLedger.cutCount += stats.cuts;
          if (this.callStack.length + stats.maxDepth > this.telemetry.maxCallDepth) {
            this.telemetry.maxCallDepth = this.callStack.length + stats.maxDepth;
            this.systemLedger.maxDepth = this.telemetry.maxCallDepth;
          }
          return dyadicMachine.conwayMul(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'ConwayLessEq') {
          const stats = dyadicMachine.countConwayLessEq(evaluatedArgs[0], evaluatedArgs[1]);
          this.telemetry.callCount += stats.calls;
          if (this.callStack.length + stats.maxDepth > this.telemetry.maxCallDepth) {
            this.telemetry.maxCallDepth = this.callStack.length + stats.maxDepth;
            this.systemLedger.maxDepth = this.telemetry.maxCallDepth;
          }
          return dyadicMachine.conwayLessEq(evaluatedArgs[0], evaluatedArgs[1]) ? 1 : 0;
        }
        if (name === 'ConwayCompare') {
          this.telemetry.callCount += 2;
          return dyadicMachine.compare(evaluatedArgs[0], evaluatedArgs[1]);
        }
        if (name === 'ConwaySort') {
          const arr = evaluatedArgs[0];
          if (Array.isArray(arr)) {
            return [...arr].sort((a, b) => dyadicMachine.compare(a, b));
          }
          return arr;
        }

        // User-defined AST function call
        const userFn = this.program.functions.get(name);
        if (userFn) {
          // Synchronous invocation using dyadicMachine implementation for recursion efficiency
          if (name === 'ConwayAdd') return dyadicMachine.conwayAdd(evaluatedArgs[0], evaluatedArgs[1]);
          if (name === 'ConwayMul') return dyadicMachine.conwayMul(evaluatedArgs[0], evaluatedArgs[1]);
          if (name === 'Cut') return dyadicMachine.cut(evaluatedArgs[0], evaluatedArgs[1]);
          if (name === 'SimplerOptions') {
            const res = dyadicMachine.simplerOptions(evaluatedArgs[0]);
            return [new Set(res.leftOptions), new Set(res.rightOptions)];
          }
        }

        throw new Error(`Unknown function call: ${name}`);
      }
    }
  }
}
